// Terrestrial Tribulations: story NPC sites (hand-written; the sites and their settings are generated by
// tools/gen_npc_sites.py into kubejs/config/tt_npc_sites.json and kubejs/data/tt/).
// - The refugee camp (Elder Maera, Doran) is placed next to world spawn once per world, because Chapter 1 opens with Maera.
// - Every other site generates naturally and stays locked until its stage (tt_meet_<npc>, given with a map by the quest
//   before that NPC's first talk): walking in without it puts you back where you stood outside, with a line.
// - The first time a player who may enter walks in, the site's NPC appears on its marker block (Easy NPC preset import),
//   once per world: other copies of the same site stay empty.
// - Moving in (config "moves"): from an NPC's stage on, the script keeps the player tag tt_invite_open_<npc>, which
//   shows "Come to Emberhold" in that NPC's menu. The button tags the player tt_invite_<npc>; the script then moves the
//   same NPC into the first built building of a listed type in the player's colony (else the Town Hall), once, and
//   stands it beside a fitting block inside (config "spots": anvil, lectern...), facing it; else by the hut block.
// Uses $TT_TagKey, $TT_Registries, $TT_ResourceLocation and ttSafe from tt_abilities.js, $TT_AABB, ttColony and
// ttBuildingManager from tt_active_abilities.js (shared scope).
// DRAFT: untested in-game.

let ttSites = null
try {
  ttSites = JsonIO.read('kubejs/config/tt_npc_sites.json')
} catch (e) { console.error(`[TT] could not read tt_npc_sites.json: ${e}`) }
const TT_SITE_TAG = $TT_TagKey.create($TT_Registries.STRUCTURE, new $TT_ResourceLocation('tt', 'npc_sites'))

ServerEvents.loaded(event => {
  const server = event.server
  if (!ttSites || server.persistentData.getBoolean('tt_npc_camp_placed')) return
  // wait a few seconds so the spawn chunks are ready
  server.scheduleInTicks(100, () => ttSafe('npc_camp', () => {
    const level = server.getLevel('minecraft:overworld')
    const spawn = level.getSharedSpawnPos()
    const x = spawn.x + 24, z = spawn.z + 8
    const ok = server.runCommandSilent(`execute in minecraft:overworld run place structure ${ttSites.camp} ${x} ${spawn.y} ${z}`)
    server.persistentData.putBoolean('tt_npc_camp_placed', true)
    console.info(`[TT] refugee camp placed near ${x} ${z} (result ${ok})`)
  }))
})

// The block of a site that carries `marker`, searched once inside the structure's bounding box.
function ttSiteMarker(level, box, marker) {
  for (let y = box.minY(); y <= box.maxY(); y++)
    for (let x = box.minX(); x <= box.maxX(); x++)
      for (let z = box.minZ(); z <= box.maxZ(); z++)
        if (String(level.getBlock(x, y, z).id) == marker) return { x: x, y: y, z: z }
  return null
}

function ttFree(level, x, y, z) {
  return String(level.getBlock(x, y - 1, z).id) != 'minecraft:air' && String(level.getBlock(x, y, z).id) == 'minecraft:air'
    && String(level.getBlock(x, y + 1, z).id) == 'minecraft:air'
}

// A free tile (solid floor, two blocks of air) beside a block, and the yaw that faces the block from it.
function ttBeside(level, pos) {
  const sides = [[0, 1], [0, -1], [1, 0], [-1, 0]]
  for (let dy = 0; dy >= -1; dy--)
    for (let i = 0; i < 4; i++) {
      const x = pos.x + sides[i][0], y = pos.y + dy, z = pos.z + sides[i][1]
      if (ttFree(level, x, y, z)) return { x: x, y: y, z: z, yaw: Math.atan2(sides[i][0], -sides[i][1]) * 180 / Math.PI }
    }
  return null
}

function ttSpotMatch(id, spot) {
  return spot.charAt(0) == '*' ? id.endsWith(spot.substring(1)) : id == spot
}

// Where an NPC stands inside a building: beside the first of its spot blocks found within the walls (earlier spots
// win), else beside the hut block, else anywhere free near the building's position.
function ttBuildingSpot(level, building, spots) {
  const pos = building.getPosition()
  let lo = pos, hi = pos
  try { let c = building.getCorners(); lo = c.getA(); hi = c.getB() } catch (e) { }
  const x0 = Math.min(lo.x, hi.x), x1 = Math.max(lo.x, hi.x), z0 = Math.min(lo.z, hi.z), z1 = Math.max(lo.z, hi.z)
  const y0 = Math.min(lo.y, hi.y), y1 = Math.max(lo.y, hi.y)
  let best = null, bestRank = spots.length
  for (let y = y0; y <= y1 && bestRank > 0; y++)
    for (let x = x0; x <= x1 && bestRank > 0; x++)
      for (let z = z0; z <= z1 && bestRank > 0; z++) {
        const id = String(level.getBlock(x, y, z).id)
        if (id == 'minecraft:air') continue
        for (let i = 0; i < bestRank; i++) {
          if (ttSpotMatch(id, spots[i])) {
            const at = ttBeside(level, { x: x, y: y, z: z })
            if (at) { best = at; bestRank = i }
            break
          }
        }
      }
  if (best) return best
  const hut = ttBeside(level, pos)
  if (hut) return hut
  for (let r = 2; r <= 5; r++)
    for (let dx = -r; dx <= r; dx++)
      for (let dz = -r; dz <= r; dz++)
        for (let dy = -1; dy <= 2; dy++)
          if (ttFree(level, pos.x + dx, pos.y + dy, pos.z + dz)) return { x: pos.x + dx, y: pos.y + dy, z: pos.z + dz, yaw: 0 }
  return { x: pos.x, y: pos.y + 1, z: pos.z, yaw: 0 }
}

// The building an NPC moves into: the first built one of its types, else the Town Hall.
function ttMoveTarget(colony, types) {
  const mgr = ttBuildingManager(colony)
  let best = null
  mgr.getBuildings().values().forEach(b => {
    if (best || b.getBuildingLevel() < 1) return
    if (types.indexOf(String(b.getBuildingType().getRegistryName())) >= 0) best = b
  })
  return best || mgr.getTownHall()
}

function ttMoveNpc(server, p, npc, mv) {
  const spd = server.persistentData
  if (spd.getBoolean('tt_npc_moved_' + npc)) return
  const colony = ttColony(p)
  const building = colony ? ttMoveTarget(colony, mv.buildings) : null
  if (!building) { p.tell(Text.gold(`${mv.name}: "Emberhold first. Plant the charter, raise a Town Hall, then ask me."`)); return }
  const box = new $TT_AABB(p.x - 16, p.y - 8, p.z - 16, p.x + 16, p.y + 8, p.z + 16)
  let found = null
  p.level.getEntitiesWithin(box).forEach(e => {
    if (!found && String(e.type).startsWith('easy_npc:') && e.customName && String(e.customName.string) == mv.name) found = e
  })
  if (!found) return
  const level = p.level, hub = building.getPosition()
  spd.putBoolean('tt_npc_moved_' + npc, true)
  p.tell(Text.of(`${mv.name}: "${mv.line}"`).gold())
  // load the building's chunk (the colony may be far away), then pick the spot and move the NPC there
  server.runCommandSilent(`execute in minecraft:overworld run forceload add ${hub.x} ${hub.z}`)
  server.scheduleInTicks(5, () => ttSafe('npc_move', () => {
    const spot = ttBuildingSpot(level, building, mv.spots)
    found.teleportTo(spot.x + 0.5, spot.y, spot.z + 0.5)
    found.setYRot(spot.yaw); found.setYHeadRot(spot.yaw); found.setYBodyRot(spot.yaw)
    console.info(`[TT] ${npc} moved into Emberhold at ${spot.x} ${spot.y} ${spot.z}`)
  }))
  server.scheduleInTicks(200, () => server.runCommandSilent(`execute in minecraft:overworld run forceload remove ${hub.x} ${hub.z}`))
}

PlayerEvents.tick(event => {
  const p = event.player
  if (!ttSites || p.level.gameTime % 20 != 7 || String(p.level.dimension) != 'minecraft:overworld') return
  ttSafe('npc_moves', () => {
    const spd = event.server.persistentData
    Object.keys(ttSites.moves || {}).forEach(npc => {
      const mv = ttSites.moves[npc]
      const open = p.stages.has(mv.stage) && spd.getBoolean('tt_npc_placed_' + npc) && !spd.getBoolean('tt_npc_moved_' + npc)
      if (open != p.stages.has('tt_invite_open_' + npc)) open ? p.stages.add('tt_invite_open_' + npc) : p.stages.remove('tt_invite_open_' + npc)
      if (p.tags.contains('tt_invite_' + npc)) {
        p.removeTag('tt_invite_' + npc)
        ttMoveNpc(event.server, p, npc, mv)
      }
    })
  })
  ttSafe('npc_sites', () => {
    const level = p.level
    const pd = p.persistentData
    const start = level.structureManager().getStructureWithPieceAt(p.blockPosition(), TT_SITE_TAG)
    if (!start || !start.isValid()) {
      // remember the last place outside every site, to send people back to
      pd.putDouble('tt_site_x', p.x); pd.putDouble('tt_site_y', p.y); pd.putDouble('tt_site_z', p.z)
      pd.putBoolean('tt_site_out', true)
      return
    }
    const id = String(level.registryAccess().registryOrThrow($TT_Registries.STRUCTURE).getKey(start.getStructure()))
    const site = ttSites.sites[id]
    if (!site) return
    if (site.stage && !p.stages.has(site.stage) && !p.isCreative() && !p.isSpectator()) {
      if (pd.getBoolean('tt_site_out')) p.teleportTo(pd.getDouble('tt_site_x'), pd.getDouble('tt_site_y'), pd.getDouble('tt_site_z'))
      else {  // no outside spot known (logged in inside): step out past the nearest edge
        const box = start.getBoundingBox()
        p.teleportTo(p.x < (box.minX() + box.maxX()) / 2 ? box.minX() - 2 : box.maxX() + 3, p.y + 1, p.z)
      }
      p.setStatusMessage(Text.of(site.locked).gold())
      return
    }
    const spd = event.server.persistentData
    Object.keys(site.npcs).forEach(npc => {
      if (spd.getBoolean('tt_npc_placed_' + npc)) return
      const m = ttSiteMarker(level, start.getBoundingBox(), site.npcs[npc].marker)
      if (!m) { console.warn(`[TT] ${id}: no ${site.npcs[npc].marker} marker for ${npc}`); return }
      spd.putBoolean('tt_npc_placed_' + npc, true)
      event.server.runCommandSilent(`execute in minecraft:overworld run easy_npc preset import_new data ${site.npcs[npc].preset} ${m.x + 0.5} ${m.y + 1} ${m.z + 0.5}`)
      console.info(`[TT] ${npc} placed at ${m.x} ${m.y + 1} ${m.z} (${id})`)
    })
  })
})
